from collections import deque

grafo = {'A': ['B', 'C'], 'B': ['A'], 'C': []}
cola = deque(['A'])
visitados = {'A'}  # Marcamos al agregar a la cola.
while cola:
    actual = cola.popleft()
    print(actual)
    for vecino in grafo[actual]:
        if vecino not in visitados:
            visitados.add(vecino)
            cola.append(vecino)
# Imprime A, B y C, cada uno en una línea.

